<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
$db=saas_db();
$slug=trim((string)($_GET['slug']??''));
$token=trim((string)($_GET['token']??''));
if($slug===''||!preg_match('/^[a-f0-9]{64}$/',$token)){http_response_code(404);exit('Booking link is invalid.');}
$hash=hash('sha256',$token);
$q=$db->prepare("SELECT tp.id tp_id,tp.status,tp.fee,tp.discount,pp.full_name,pp.phone,pp.email,t.id tour_id,t.name tour_name,t.slug,t.start_date,t.end_date,t.description,o.name organization_name,o.currency,ppub.status page_status,ppub.title page_title,ppub.subtitle,ppub.cover_image,ppub.logo_image,ppub.primary_color,ppub.secondary_color FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id JOIN tour_public_pages ppub ON ppub.tour_id=t.id WHERE t.slug=? AND tp.booking_access_token_hash=? AND tp.booking_access_token_revoked_at IS NULL AND o.status='ACTIVE' LIMIT 1");
$q->execute([$slug,$hash]);$booking=$q->fetch();
if(!$booking||$booking['status']!=='ACTIVE'){http_response_code(404);exit('Active booking not found.');}
$q=$db->prepare("SELECT b.id,b.name,b.bus_number,b.layout_type,(SELECT COUNT(*) FROM seats s WHERE s.bus_id=b.id AND s.status='AVAILABLE') seat_count,(SELECT COUNT(*) FROM passenger_seat_assignments psa WHERE psa.bus_id=b.id) assigned_count FROM buses b WHERE b.tour_id=? AND b.status='ACTIVE' ORDER BY b.id");
$q->execute([(int)$booking['tour_id']]);$buses=$q->fetchAll();
$q=$db->prepare("SELECT r.id,r.room_no,r.room_type,r.capacity,r.status,(SELECT COUNT(*) FROM room_assignments ra WHERE ra.room_id=r.id) occupied FROM rooms r WHERE r.tour_id=? ORDER BY r.room_no");
$q->execute([(int)$booking['tour_id']]);$rooms=$q->fetchAll();
$q=$db->prepare("SELECT s.seat_code,b.name bus_name,b.bus_number FROM passenger_seat_assignments psa JOIN seats s ON s.id=psa.seat_id JOIN buses b ON b.id=psa.bus_id WHERE psa.tour_passenger_id=? LIMIT 1");$q->execute([(int)$booking['tp_id']]);$seat=$q->fetch();
$q=$db->prepare("SELECT r.room_no,r.room_type FROM room_assignments ra JOIN rooms r ON r.id=ra.room_id WHERE ra.tour_passenger_id=? LIMIT 1");$q->execute([(int)$booking['tp_id']]);$room=$q->fetch();
$paid=(float)($db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_passenger_id=? AND tour_id=?')->execute([(int)$booking['tp_id'],(int)$booking['tour_id']])?:0);
$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_passenger_id=? AND tour_id=?');$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id']]);$paid=(float)$q->fetchColumn();
$total=max(0,(float)$booking['fee']-(float)$booking['discount']);$due=max(0,$total-$paid);
$base=rtrim(dirname((string)($_SERVER['SCRIPT_NAME']??'/')),'/');
$seatUrl=$base.'/public_seat_select.php?slug='.rawurlencode($slug).'&token='.rawurlencode($token);
$roomUrl=$base.'/public_room_select.php?slug='.rawurlencode($slug).'&token='.rawurlencode($token);
$primary=$booking['primary_color']?:'#155eef';$secondary=$booking['secondary_color']?:'#0f172a';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=saas_h($booking['page_title']?:$booking['tour_name'])?> — My Booking</title><style>:root{--p:<?=saas_h($primary)?>;--s:<?=saas_h($secondary)?>}*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Inter,system-ui,Arial,sans-serif}.hero{background:linear-gradient(135deg,var(--s),var(--p));color:#fff;padding:42px 20px}.hero-inner,.wrap{width:min(1050px,100%);margin:auto}.hero-inner{padding:0 16px}.hero h1{margin:8px 0;font-size:clamp(30px,5vw,48px)}.wrap{padding:22px 16px 50px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.card{background:#fff;border-radius:16px;padding:20px;box-shadow:0 8px 30px #0000000b;margin-bottom:16px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{padding:14px;border-radius:12px;background:#f8fafc}.label{font-size:12px;color:#667085}.value{font-size:20px;font-weight:800;margin-top:3px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}.btn{display:block;text-align:center;text-decoration:none;padding:12px;border-radius:10px;background:var(--p);color:#fff;font-weight:800}.btn.secondary{background:#eef4ff;color:#175cd3}.muted{color:#667085;font-size:14px}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#ecfdf3;color:#067647;font-size:12px;font-weight:700}.due{color:#b42318}.paid{color:#067647}@media(max-width:700px){.grid{grid-template-columns:1fr}.stats,.actions{grid-template-columns:1fr}}</style></head><body><header class="hero"><div class="hero-inner"><div><?=saas_h($booking['organization_name'])?></div><h1><?=saas_h($booking['page_title']?:$booking['tour_name'])?></h1><p><?=saas_h($booking['page_subtitle']??'Your booking dashboard')?></p></div></header><main class="wrap"><section class="card"><h2>Welcome, <?=saas_h($booking['full_name'])?></h2><p><?=saas_h($booking['phone'])?><?=($booking['email']?' · '.saas_h($booking['email']):'')?></p><span class="badge">Booking confirmed</span></section><section class="card"><h2>Booking summary</h2><div class="stats"><div class="stat"><div class="label">Tour fee</div><div class="value"><?=number_format($total,2)?> <?=saas_h($booking['currency'])?></div></div><div class="stat"><div class="label">Paid</div><div class="value paid"><?=number_format($paid,2)?> <?=saas_h($booking['currency'])?></div></div><div class="stat"><div class="label">Due</div><div class="value <?=($due>0?'due':'paid')?>"><?=number_format($due,2)?> <?=saas_h($booking['currency'])?></div></div></div></section><div class="grid"><section class="card"><h2>Seat</h2><?php if($seat):?><p><strong><?=saas_h($seat['seat_code'])?></strong> · <?=saas_h($seat['bus_name'])?><?=($seat['bus_number']?' · '.saas_h($seat['bus_number']):'')?></p><?php else:?><p class="muted">No seat selected yet.</p><?php endif;?><a class="btn" href="<?=saas_h($seatUrl)?>"><?=($seat?'Change seat':'Select seat')?></a></section><section class="card"><h2>Room</h2><?php if($room):?><p><strong><?=saas_h($room['room_no'])?></strong> · <?=saas_h($room['room_type'])?></p><?php else:?><p class="muted">No room selected yet.</p><?php endif;?><a class="btn" href="<?=saas_h($roomUrl)?>"><?=($room?'Change room':'Select room')?></a></section></div><section class="card"><h2>Tour information</h2><p><?=saas_h($booking['start_date']?:'To be announced')?><?=($booking['end_date']?' → '.saas_h($booking['end_date']):'')?></p><?php if($booking['description']):?><p class="muted"><?=nl2br(saas_h($booking['description']))?></p><?php endif;?></section><section class="card"><h2>Payment</h2><?php if($due>0):?><p class="muted">Your remaining balance is <strong class="due"><?=number_format($due,2)?> <?=saas_h($booking['currency'])?></strong>.</p><p class="muted">Online payment checkout will be enabled here when a payment gateway is connected.</p><?php else:?><p class="paid"><strong>Paid in full.</strong></p><?php endif;?></section></main></body></html>